{
  // Specify the settings for the workspace email notification channel here.
  // See https://docs.unstructured.io/api-reference/email
  // API reference: https://docs.unstructured.io/api-reference/api/notification/create-notification-channel
  "channel_type": "email",
  "event_types": ["job.scheduled", "job.in_progress", "job.completed", "job.stopped", "job.failed"],
  "description": "Workspace level job events",
  "email_config": {
    "recipient_email": "donotreply@example.com"
  }
}

{
  // Enter the 6-digit verification code sent to the recipient email address.
  // See https://docs.unstructured.io/api-reference/email#verify-the-email-channel
  // API reference: https://docs.unstructured.io/api-reference/api/notification/verify-notification-channel
  "verification_code": "123456"
}

{
  // Specify the fields to update for the workspace email notification channel here.
  // See https://docs.unstructured.io/api-reference/email
  // API reference: https://docs.unstructured.io/api-reference/api/notification/update-notification-channel
  "event_types": ["job.scheduled", "job.in_progress", "job.completed", "job.stopped", "job.failed"],
  "email_config": {
    "recipient_email": "donotreply@example.com"
  },
  "enabled": true
}

{
  // Specify the settings for the workflow email notification channel here.
  // See https://docs.unstructured.io/api-reference/email
  // API reference: https://docs.unstructured.io/api-reference/api/workflow/create-workflow-notification-channel
  "channel_type": "email",
  "event_types": ["job.scheduled", "job.in_progress", "job.completed", "job.stopped", "job.failed"],
  "description": "Workflow-specific status alerts",
  "email_config": {
    "recipient_email": "donotreply@example.com"
  }
}

{
  // Enter the 6-digit verification code sent to the recipient email address.
  // See https://docs.unstructured.io/api-reference/email#verify-the-email-channel
  // API reference: https://docs.unstructured.io/api-reference/api/workflow/verify-workflow-notification-channel
  "verification_code": "123456"
}

{
  // Specify the fields to update for the workflow email notification channel here.
  // See https://docs.unstructured.io/api-reference/email
  // API reference: https://docs.unstructured.io/api-reference/api/workflow/update-workflow-notification-channel
  "event_types": ["job.scheduled", "job.in_progress", "job.completed", "job.stopped", "job.failed"],
  "email_config": {
    "recipient_email": "donotreply@example.com"
  },
  "enabled": true
}
